def transform(grid):
    # Superimpose the two panels separated by the vertical 6 divider;
    # intersections of their marked cells become color 2.
    sep = next(c for c in range(len(grid[0])) if len({row[c] for row in grid}) == 1)
    return [[2 if row[c] != 0 and row[c + sep + 1] != 0 else 0
             for c in range(sep)] for row in grid]

